"use client";

import { memo, useCallback, useId, useMemo, useState } from "react";
import type { FocusEvent, ReactNode } from "react";
import { cn } from "@/lib/utils";
import {
  defaultExpandableTextLabels,
  type ExpandableTextLabels,
  type ExpandableTextProps,
} from "./types";
import { useLineClampDetect } from "./hooks/use-line-clamp-detect";

/** Nothing React would render (`null`, `false`, `""`, empty arrays…). */
const isEmptyNode = (node: ReactNode): boolean =>
  node === null ||
  node === undefined ||
  typeof node === "boolean" ||
  node === "" ||
  (Array.isArray(node) && node.every(isEmptyNode));

const UNCLAMP_WITHOUT_TOGGLE =
  "print:overflow-visible! print:max-h-none! print:[-webkit-line-clamp:unset]! [@media(scripting:none)]:overflow-visible! [@media(scripting:none)]:max-h-none! [@media(scripting:none)]:[-webkit-line-clamp:unset]!";

/** Merge `labels` over the defaults — an `undefined` key never erases a default (C2). */
function resolveLabels(labels: ExpandableTextLabels | undefined): Required<ExpandableTextLabels> {
  return {
    showMore: labels?.showMore ?? defaultExpandableTextLabels.showMore,
    showLess: labels?.showLess ?? defaultExpandableTextLabels.showLess,
  };
}

function ExpandableTextInner({
  content,
  children,
  measureKey,
  maxLines = 3,
  dir = "auto",
  expanded: expandedProp,
  defaultExpanded = false,
  onExpandedChange,
  labels: labelsProp,
  renderToggle,
  className,
  contentClassName,
  toggleClassName,
}: ExpandableTextProps) {
  const labels = useMemo(() => resolveLabels(labelsProp), [labelsProp]);

  const isControlled = expandedProp !== undefined;
  const [expandedState, setExpandedState] = useState(defaultExpanded);
  const expanded = isControlled ? expandedProp : expandedState;

  const setExpanded = useCallback(
    (next: boolean) => {
      if (!isControlled) setExpandedState(next);
      onExpandedChange?.(next);
    },
    [isControlled, onExpandedChange],
  );

  const rich = !isEmptyNode(children);
  // Re-measure on a new `content` or `measureKey`; rich children are also watched for DOM changes.
  const measureTrigger = useMemo(() => [content, measureKey], [content, measureKey]);
  const { ref, isTruncated, isMeasured } = useLineClampDetect({
    maxLines,
    content: measureTrigger,
    observeMutations: rich,
  });
  const contentId = useId();

  // Clamped from the first paint (the server cannot measure) — no full-text flash and layout
  // shift on hydration. After measuring, text that fits is unclamped (nothing to clip).
  const isClamped = !expanded && (isTruncated || !isMeasured);
  const showToggle = isTruncated;

  // Keyboard focus moving onto a link BELOW the clamp would land on hidden content: expand instead
  // (controlled: ask the parent). A link on a visible line, or a mouse click, does not expand.
  const handleFocus = useCallback(
    (e: FocusEvent<HTMLElement>) => {
      if (expanded || !isTruncated) return;
      const target = e.target as Element;
      let keyboard = false;
      try {
        keyboard = target.matches(":focus-visible");
      } catch {
        // `:focus-visible` unsupported — treat as pointer focus.
      }
      if (!keyboard) return;
      const box = e.currentTarget;
      // Browsers scroll the clipped box to reveal the focused element BEFORE `focus` fires, so a
      // scrolled box is the signal; the geometry check covers engines that do not scroll it.
      const hidden =
        box.scrollTop > 0 || target.getBoundingClientRect().bottom > box.getBoundingClientRect().bottom + 1;
      if (!hidden) return;
      box.scrollTop = 0;
      setExpanded(true);
    },
    [expanded, isTruncated, setExpanded],
  );

  if (!rich && !content) return null;

  const Content = rich ? "div" : "p";

  return (
    <div className={cn(className)}>
      <Content
        ref={ref}
        id={contentId}
        dir={dir}
        onFocus={handleFocus}
        className={cn(
          "text-sm leading-relaxed whitespace-pre-wrap wrap-break-word",
          // Printing, or a browser without scripting (no toggle can run): show everything.
          UNCLAMP_WITHOUT_TOGGLE,
          contentClassName,
        )}
        style={{
          display: "-webkit-box",
          WebkitBoxOrient: "vertical",
          WebkitLineClamp: isClamped ? maxLines : "unset",
          // `-webkit-line-clamp` does not hold for block children (two <p> clamp at ~4.6 lines):
          // bound rich content by its line height too. Inline children keep the ellipsis.
          maxHeight: isClamped && rich ? `${maxLines}lh` : undefined,
          overflow: isClamped ? "hidden" : "visible",
        }}
      >
        {rich ? children : content}
      </Content>
      {showToggle &&
        (renderToggle ? (
          renderToggle({ isExpanded: expanded, setExpanded })
        ) : (
          <button
            type="button"
            onClick={() => setExpanded(!expanded)}
            aria-expanded={expanded}
            aria-controls={contentId}
            className={cn(
              "mt-1 rounded-sm text-sm font-medium text-muted-foreground motion-safe:transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              toggleClassName,
            )}
          >
            {expanded ? labels.showLess : labels.showMore}
          </button>
        ))}
    </div>
  );
}

const ExpandableText = memo(ExpandableTextInner);
ExpandableText.displayName = "ExpandableText";

export { ExpandableText };
export default ExpandableText;

export { default as ExpandableText } from "./expandable-text";

export type {
  ExpandableTextProps,
  ExpandableTextLabels,
  ExpandableTextToggleRenderProps,
} from "./types";

export { DEFAULT_EXPANDABLE_TEXT_LABELS, defaultExpandableTextLabels } from "./types";

export {
  useLineClampDetect,
  type UseLineClampDetectOptions,
  type UseLineClampDetectResult,
} from "./hooks/use-line-clamp-detect";

// @ilinxa/expandable-text 0.3.0

import type { ReactNode } from "react";

export interface ExpandableTextLabels {
  /** Default: "Show more". Toggle button label when collapsed. */
  showMore?: string;
  /** Default: "Show less". Toggle button label when expanded. */
  showLess?: string;
}

export interface ExpandableTextToggleRenderProps {
  /** Current expanded state. */
  isExpanded: boolean;
  /** Setter — handles controlled-or-uncontrolled internally. */
  setExpanded: (next: boolean) => void;
}

export interface ExpandableTextProps {
  /**
   * Plain-text content. Rendered in a `<p>`. Ignored when `children` is given. The component renders
   * nothing when there is neither non-empty `content` nor renderable `children`.
   */
  content?: string | null;

  /**
   * Rich content — your own link / mention renderer. Wins over `content`. Rendered in a `<div>`, so block
   * children (a `<p>` per paragraph) are valid. Changes inside it are re-measured automatically; pass
   * `measureKey` for changes that alter no DOM (a web font finishing loading).
   */
  children?: ReactNode;

  /** Re-measure the clamp whenever this value changes. */
  measureKey?: unknown;

  /** Number of lines before truncation. Default: 3. */
  maxLines?: number;

  /** Text direction of the content element. Default: "auto" (bidi isolation — an Arabic post in an LTR feed starts at the right). */
  dir?: "auto" | "ltr" | "rtl";

  // ─── Controlled-or-uncontrolled expanded state ──────────────────
  /** Controlled expanded state — wins on every render. Pair with `onExpandedChange`. */
  expanded?: boolean;
  /** Initial uncontrolled expanded state. Default: false. Ignored when `expanded` is provided. */
  defaultExpanded?: boolean;
  /**
   * Fires on every requested expand/collapse with the NEXT state — the toggle, and keyboard focus moving
   * into clamped content (which asks to expand, so focus never lands on hidden text).
   */
  onExpandedChange?: (next: boolean) => void;

  // ─── Customization ────────────────────────────────
  /** Localized labels. Defaults are English; an `undefined` key keeps its default. */
  labels?: ExpandableTextLabels;
  /** Custom toggle renderer — full takeover. Receives current state + setter. */
  renderToggle?: (props: ExpandableTextToggleRenderProps) => ReactNode;

  // ─── Style overrides ─────────────────────────────
  /** Override classes for the wrapping <div>. */
  className?: string;
  /** Override classes for the content element (`<p>` for `content`, `<div>` for `children`). */
  contentClassName?: string;
  /** Override classes for the default toggle <button>. Ignored when `renderToggle` is provided. */
  toggleClassName?: string;
}

/** Default English labels — exported for consumer composition. */
export const defaultExpandableTextLabels: Required<ExpandableTextLabels> = {
  showMore: "Show more",
  showLess: "Show less",
};

/** @deprecated Use `defaultExpandableTextLabels` — the same object under its old name. */
export const DEFAULT_EXPANDABLE_TEXT_LABELS: Required<ExpandableTextLabels> = defaultExpandableTextLabels;

import { useEffect, useLayoutEffect, useState } from "react";

const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export interface UseLineClampDetectOptions {
  maxLines: number;
  /**
   * Re-measurement trigger. Hook never reads the value — only uses its
   * identity to detect when re-measurement is needed. Pass a primitive
   * (string, number), a content hash, or any stable identity that changes
   * when the underlying text changes.
   */
  content: unknown;
  /**
   * Also re-measure when the element's DOM changes (text or children) — for rich
   * children whose changes do not resize a clamped box. Default: false.
   */
  observeMutations?: boolean;
}

export interface UseLineClampDetectResult {
  /** Pass to your measured element: `<p ref={ref}>...</p>`. */
  ref: (node: HTMLElement | null) => void;
  /** True when the element's natural height exceeds `maxLines × lineHeight`. */
  isTruncated: boolean;
  /** False until the first measurement ran (always false on the server). */
  isMeasured: boolean;
}

/** `line-height: normal` has no px value — approximate it the way browsers do (~1.2 × font size). */
function lineHeightOf(el: HTMLElement): number {
  const style = getComputedStyle(el);
  const lh = parseFloat(style.lineHeight);
  if (lh && !Number.isNaN(lh)) return lh;
  const fs = parseFloat(style.fontSize);
  return fs && !Number.isNaN(fs) ? fs * 1.2 : 0;
}

/**
 * Detect whether content overflows a line-clamp threshold.
 *
 * Measures `scrollHeight` against `lineHeight × maxLines` after mount and on
 * every container resize (via `ResizeObserver`), and — with `observeMutations` —
 * on DOM changes inside the element. Returns `isTruncated: true` only when the
 * content's natural height exceeds the budget — so consumers can hide their
 * "show more" toggle when content fits.
 *
 * The element is tracked via `useState` (not a `useRef` capture) so identity
 * changes — e.g., consumer attaches the ref to a `<p>` inside a list with
 * keys → re-mounts on reorder — re-trigger the observer setup.
 */
export function useLineClampDetect({
  maxLines,
  content,
  observeMutations = false,
}: UseLineClampDetectOptions): UseLineClampDetectResult {
  const [el, setEl] = useState<HTMLElement | null>(null);
  const [isTruncated, setIsTruncated] = useState(false);
  const [isMeasured, setIsMeasured] = useState(false);

  // Layout effect: the first measurement (and one after a content change) lands before paint, so
  // text that grew while unclamped never paints a frame at full length.
  useIsoLayoutEffect(() => {
    if (!el) return;

    const measure = () => {
      const lineHeight = lineHeightOf(el);
      // No usable line height (no layout engine, `font-size: 0`): treat as not truncated, so a
      // caller that clamps until measured never leaves text cut off with no way to expand it.
      const next = lineHeight ? el.scrollHeight > lineHeight * maxLines + 1 : false; // +1 sub-pixel slop
      setIsTruncated((prev) => (prev === next ? prev : next));
      setIsMeasured(true);
    };

    measure(); // initial synchronous measurement
    const resize = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(measure);
    resize?.observe(el);
    const mutation =
      observeMutations && typeof MutationObserver !== "undefined" ? new MutationObserver(measure) : null;
    mutation?.observe(el, { childList: true, subtree: true, characterData: true });
    return () => {
      resize?.disconnect();
      mutation?.disconnect();
    };
  }, [el, content, maxLines, observeMutations]);

  return { ref: setEl, isTruncated, isMeasured };
}
